'use strict'

const fs = require('node:fs')
const path = require('node:path')

const root = path.resolve(__dirname, '..')

function patchIndexJs(file) {
  let source = fs.readFileSync(file, 'utf8')

  source = source.replace(
    "\nconst { createRequire } = require('node:module')\nrequire = createRequire(__filename)\n",
    '',
  )
  source = source.replace(
    '/* auto-generated by NAPI-RS */\n\n\nconst { readFileSync }',
    '/* auto-generated by NAPI-RS */\n\nconst { readFileSync }',
  )
  source = source.replace(
    'nativeBinding = require(process.env.NAPI_RS_NATIVE_LIBRARY_PATH);',
    'return require(process.env.NAPI_RS_NATIVE_LIBRARY_PATH);',
  )

  source = replaceBetween(
    source,
    "  } else if (process.platform === 'win32') {\n",
    "    } else if (process.arch === 'ia32') {",
    WIN32_X64_BLOCK,
  )

  if (!source.includes('atto_ui_node.linux-loong64-musl.node')) {
    source = source.replace(
      "    } else if (process.arch === 'riscv64') {",
      `${LOONG64_BLOCK}    } else if (process.arch === 'riscv64') {`,
    )
  }

  if (source.includes('if (!nativeBinding || process.env.NAPI_RS_FORCE_WASI) {')) {
    source = replaceWholeBetween(
      source,
      'if (!nativeBinding || process.env.NAPI_RS_FORCE_WASI) {',
      '\n\nif (!nativeBinding) {',
      WASI_BLOCK,
    )
  } else if (!source.includes('const forceWasi =')) {
    throw new Error('Could not find generated or patched WASI binding block')
  }

  source = source.replace(
    '      { cause: loadErrors }',
    `      {\n        cause: loadErrors.reduce((err, cur) => {\n          cur.cause = err\n          return cur\n        }),\n      },`,
  )
  source = source.replace(
    `        }),\n      }\n    )`,
    `        }),\n      },\n    )`,
  )

  fs.writeFileSync(file, source, 'utf8')
}

function patchDts(file) {
  let source = fs.readFileSync(file, 'utf8')
  if (source.includes('export type ComponentValue =')) {
    return
  }
  source = source.replace(
    '/** Register optional runtime components from workspace companion crates. */',
    `${DTS_TYPES}\n/** Register optional runtime components from workspace companion crates. */`,
  )
  fs.writeFileSync(file, source, 'utf8')
}

function replaceBetween(source, start, end, replacement) {
  const startIndex = source.indexOf(start)
  if (startIndex === -1) {
    throw new Error(`Could not find start marker: ${start}`)
  }
  const bodyStart = startIndex + start.length
  const endIndex = source.indexOf(end, bodyStart)
  if (endIndex === -1) {
    throw new Error(`Could not find end marker: ${end}`)
  }
  return source.slice(0, bodyStart) + replacement + source.slice(endIndex)
}

function replaceWholeBetween(source, start, end, replacement) {
  const startIndex = source.indexOf(start)
  if (startIndex === -1) {
    throw new Error(`Could not find start marker: ${start}`)
  }
  const endIndex = source.indexOf(end, startIndex + start.length)
  if (endIndex === -1) {
    throw new Error(`Could not find end marker: ${end}`)
  }
  return source.slice(0, startIndex) + replacement + source.slice(endIndex)
}

const WIN32_X64_BLOCK = `    if (process.arch === 'x64') {
      if (process.config?.variables?.shlib_suffix === 'dll.a' || process.config?.variables?.node_target_type === 'shared_library') {
        try {
        return require('./atto_ui_node.win32-x64-gnu.node')
      } catch (e) {
        loadErrors.push(e)
      }
      try {
        const binding = require('@atto-ui/node-win32-x64-gnu')
        const bindingPackageVersion = require('@atto-ui/node-win32-x64-gnu/package.json').version
        if (bindingPackageVersion !== '0.1.0' && process.env.NAPI_RS_ENFORCE_VERSION_CHECK && process.env.NAPI_RS_ENFORCE_VERSION_CHECK !== '0') {
          throw new Error(\`Native binding package version mismatch, expected 0.1.0 but got \${bindingPackageVersion}. You can reinstall dependencies to fix this issue.\`)
        }
        return binding
      } catch (e) {
        loadErrors.push(e)
      }
      } else {
        try {
        return require('./atto_ui_node.win32-x64-msvc.node')
      } catch (e) {
        loadErrors.push(e)
      }
      try {
        const binding = require('@atto-ui/node-win32-x64-msvc')
        const bindingPackageVersion = require('@atto-ui/node-win32-x64-msvc/package.json').version
        if (bindingPackageVersion !== '0.1.0' && process.env.NAPI_RS_ENFORCE_VERSION_CHECK && process.env.NAPI_RS_ENFORCE_VERSION_CHECK !== '0') {
          throw new Error(\`Native binding package version mismatch, expected 0.1.0 but got \${bindingPackageVersion}. You can reinstall dependencies to fix this issue.\`)
        }
        return binding
      } catch (e) {
        loadErrors.push(e)
      }
      }
`

const LOONG64_BLOCK = `    } else if (process.arch === 'loong64') {
      if (isMusl()) {
        try {
          return require('./atto_ui_node.linux-loong64-musl.node')
        } catch (e) {
          loadErrors.push(e)
        }
        try {
          const binding = require('@atto-ui/node-linux-loong64-musl')
          const bindingPackageVersion = require('@atto-ui/node-linux-loong64-musl/package.json').version
          if (bindingPackageVersion !== '0.1.0' && process.env.NAPI_RS_ENFORCE_VERSION_CHECK && process.env.NAPI_RS_ENFORCE_VERSION_CHECK !== '0') {
            throw new Error(\`Native binding package version mismatch, expected 0.1.0 but got \${bindingPackageVersion}. You can reinstall dependencies to fix this issue.\`)
          }
          return binding
        } catch (e) {
          loadErrors.push(e)
        }
      } else {
        try {
          return require('./atto_ui_node.linux-loong64-gnu.node')
        } catch (e) {
          loadErrors.push(e)
        }
        try {
          const binding = require('@atto-ui/node-linux-loong64-gnu')
          const bindingPackageVersion = require('@atto-ui/node-linux-loong64-gnu/package.json').version
          if (bindingPackageVersion !== '0.1.0' && process.env.NAPI_RS_ENFORCE_VERSION_CHECK && process.env.NAPI_RS_ENFORCE_VERSION_CHECK !== '0') {
            throw new Error(\`Native binding package version mismatch, expected 0.1.0 but got \${bindingPackageVersion}. You can reinstall dependencies to fix this issue.\`)
          }
          return binding
        } catch (e) {
          loadErrors.push(e)
        }
      }
`

const WASI_BLOCK = `// NAPI_RS_FORCE_WASI is a tri-state flag:
//   unset / any other value \u2192 native binding preferred, WASI is only a fallback
//   'true'                   \u2192 force WASI fallback even if native loaded
//   'error'                  \u2192 force WASI and throw if no WASI binding is found
// Treating any non-empty string as truthy (the historical behavior) meant
// NAPI_RS_FORCE_WASI=false, NAPI_RS_FORCE_WASI=0, etc. inadvertently triggered
// the WASI path, causing ENOENT for packages shipped without a .wasi.cjs file.
const forceWasi =
  process.env.NAPI_RS_FORCE_WASI === 'true' || process.env.NAPI_RS_FORCE_WASI === 'error'

if (!nativeBinding || forceWasi) {
  let wasiBinding = null
  let wasiBindingError = null
  try {
    wasiBinding = require('./atto_ui_node.wasi.cjs')
    nativeBinding = wasiBinding
  } catch (err) {
    if (forceWasi) {
      wasiBindingError = err
    }
  }
  if (!nativeBinding || forceWasi) {
    try {
      wasiBinding = require('@atto-ui/node-wasm32-wasi')
      nativeBinding = wasiBinding
    } catch (err) {
      if (forceWasi) {
        if (!wasiBindingError) {
          wasiBindingError = err
        } else {
          wasiBindingError.cause = err
        }
        loadErrors.push(err)
      }
    }
  }
  if (process.env.NAPI_RS_FORCE_WASI === 'error' && !wasiBinding) {
    const error = new Error('WASI binding not found and NAPI_RS_FORCE_WASI is set to error')
    error.cause = wasiBindingError
    throw error
  }
}`

const DTS_TYPES = `/** JavaScript-facing value accepted by runtime component props. */
export type ComponentValue =
  | null
  | boolean
  | number
  | string
  | readonly string[]
  | readonly (readonly string[])[]
  | Uint8Array
  | Rect
  | readonly ComponentValue[]
  | { readonly [key: string]: ComponentValue }

export type ChatRole = 'user' | 'assistant' | 'system' | \`custom:\${string}\`
export type ChatErrorKind = 'api' | 'tool' | 'rate_limit' | 'refusal' | 'network' | 'other'
export type ChatTurnStatus = 'complete' | 'streaming' | 'canceled' | { readonly failed: ChatError }
export type ChatToolStatus = 'pending' | 'running' | 'done' | 'error' | 'canceled'
export type ChatArtifactKind = 'code' | 'diff' | 'file' | (string & {})
export type ChatEditDecision = 'pending' | 'accepted' | 'rejected'
export type ChatPlanDecision = 'pending' | 'accepted' | 'rejected'
export type ChatTaskStatus = 'pending' | 'running' | 'complete' | 'failed' | 'canceled'
export type ChatTodoState = 'pending' | 'in_progress' | 'done'
export type ChatNoticeLevel = 'info' | 'warning' | 'error'
export type ChatCompactStatus = 'pending' | 'running' | 'complete' | 'failed' | 'canceled'
export type ChatApprovalAction = 'allow' | 'deny'
export type ChatApprovalLevel = 'once' | 'always' | 'project'
export type StopReason = 'end_turn' | 'max_tokens' | 'tool_use' | 'stop_sequence' | 'refusal'
export type ChatSlashCommandAction = 'insert' | 'submit'

export interface ChatError {
  readonly kind: ChatErrorKind
  readonly message: string
  readonly detail?: string
}

export interface ChatMessageMeta {
  readonly timestamp?: string | null
  readonly model?: string
  readonly usage?: { readonly input: number; readonly output: number }
  readonly elapsed_ms?: number
  readonly stop_reason?: StopReason
}

export type ChatToolInput = { readonly text: string } | { readonly json: ComponentValue }
export type ChatToolOutput = { readonly ansi: string } | { readonly markdown: string } | { readonly diff: string }

export interface ChatApprovalRequest {
  readonly id: string
  readonly prompt: string
  readonly options: readonly { readonly id: string; readonly label: string; readonly action?: ChatApprovalAction; readonly level?: ChatApprovalLevel }[]
  readonly resolved?: string
  readonly resolved_action?: ChatApprovalAction
  readonly resolved_level?: ChatApprovalLevel
}

export interface ChatApprovalDecisionValue {
  readonly message_id: number
  readonly block_id: number
  readonly approval_id: string
  readonly option_id: string
  readonly action: ChatApprovalAction
  readonly level: ChatApprovalLevel
}

export type ChatBlock =
  | { readonly type: 'text'; readonly block_id: number; readonly markdown: string; readonly streaming?: boolean }
  | { readonly type: 'thinking'; readonly block_id: number; readonly markdown: string; readonly streaming?: boolean; readonly collapsed?: boolean }
  | { readonly type: 'tool_use'; readonly block_id: number; readonly call_id: string; readonly name: string; readonly input: ChatToolInput; readonly status: ChatToolStatus; readonly approval?: ChatApprovalRequest; readonly collapsed?: boolean }
  | { readonly type: 'tool_result'; readonly block_id: number; readonly call_id: string; readonly ok: boolean; readonly exit_code?: number; readonly output: ChatToolOutput; readonly collapsed?: boolean }
  | { readonly type: 'diff'; readonly block_id: number; readonly path: string; readonly diff: string; readonly decision: ChatEditDecision }
  | { readonly type: 'plan'; readonly block_id: number; readonly items: readonly { readonly text: string }[]; readonly decision: ChatPlanDecision }
  | { readonly type: 'task'; readonly block_id: number; readonly title: string; readonly status: ChatTaskStatus; readonly summary: string; readonly transcript: readonly { readonly role: ChatRole; readonly blocks: readonly ChatBlock[] }[]; readonly collapsed?: boolean }
  | { readonly type: 'todo'; readonly block_id: number; readonly items: readonly { readonly text: string; readonly state: ChatTodoState }[] }
  | { readonly type: 'attachment'; readonly block_id: number; readonly name: string; readonly url?: string | null; readonly mime?: string | null }
  | { readonly type: 'notice'; readonly block_id: number; readonly level: ChatNoticeLevel; readonly text: string }
  | { readonly type: 'compact'; readonly block_id: number; readonly status: ChatCompactStatus; readonly before_tokens?: number | null; readonly after_tokens?: number | null; readonly summary: string }
  | { readonly type: 'artifact'; readonly block_id: number; readonly kind: ChatArtifactKind; readonly anchor: string | number; readonly title: string }

export interface ChatMessageValue {
  readonly id: number
  readonly role: ChatRole
  readonly status: ChatTurnStatus
  readonly meta?: ChatMessageMeta
  readonly blocks: readonly ChatBlock[]
}

export interface ChatSlashCommandValue {
  readonly id?: string
  readonly label: string
  readonly detail?: string | null
  readonly replacement?: string
  readonly action?: ChatSlashCommandAction
}

export interface ChatMentionCandidateValue {
  readonly id?: string
  readonly label: string
  readonly detail?: string | null
  readonly replacement?: string
}

export interface ChatMentionContextValue {
  readonly draft: string
  readonly query: string
  readonly cursor: number
  readonly replacement_start: number
  readonly replacement_end: number
}
`

patchIndexJs(path.join(root, 'index.js'))
patchDts(path.join(root, 'index.d.ts'))
